PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,email TEXT UNIQUE,password_hash TEXT,age INTEGER DEFAULT 21,gender TEXT DEFAULT 'Prefer not to say',height_cm REAL DEFAULT 170,weight_kg REAL DEFAULT 70,fitness_level TEXT DEFAULT 'Intermediate',bio TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workouts(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,category TEXT,difficulty TEXT,duration_min INTEGER,calories INTEGER,description TEXT,equipment TEXT);
CREATE TABLE IF NOT EXISTS workout_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,workout_id INTEGER,completed_at TEXT DEFAULT CURRENT_TIMESTAMP,duration_min INTEGER,calories INTEGER,rating INTEGER DEFAULT 5,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(workout_id) REFERENCES workouts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS meals(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,meal_type TEXT,name TEXT,calories INTEGER DEFAULT 0,protein_g REAL DEFAULT 0,carbs_g REAL DEFAULT 0,fats_g REAL DEFAULT 0,logged_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS goals(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,title TEXT,target_value REAL,current_value REAL DEFAULT 0,unit TEXT,category TEXT,due_date TEXT,status TEXT DEFAULT 'active',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS progress(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,weight_kg REAL,body_fat REAL DEFAULT 0,recorded_on TEXT,note TEXT DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS water_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,glasses INTEGER,logged_date TEXT,UNIQUE(user_id,logged_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);